import os

query = "SELECT * FROM test/sample.csv WHERE name = 'test/sample.csv'"

# We want to replace files that are unquoted, but maybe also quoted.
# A regex that extracts potential filenames (words with slashes and dots)
def replace_files(q):
    tokens = re.split(r'(\s+|,|\(|\))', q)
    for i, t in enumerate(tokens):
        # strip quotes to check if file exists
        clean_t = t.strip('`"\'')
        if clean_t and os.path.isfile(clean_t):
            # Just replace if it wasn't already quoted with backticks
            if not t.startswith('`'):
                tokens[i] = f'`{clean_t}`'
    return "".join(tokens)

print(replace_files(query))
