#!/usr/bin/env python3
import sys, os, csv, json, re, sqlite3, io

def parse_args():
    FLAG_ARITY = {
        '-A': 1, '-a': 1, '-config': 1, '-db': 1, '-dblist': 0, '-debug': 0, '-driver': 1, '-dsn': 1,
        '-help': 0, '-q': 1, '-t': 1, '-version': 0, '-icsv': 0, '-ig': 0, '-ijson': 0, '-iltsv': 0,
        '-itbln': 0, '-itext': 0, '-iwidth': 0, '-iyaml': 0, '-id': 1, '-ih': 0, '-ijq': 1, '-ilr': 1,
        '-inull': 1, '-inum': 0, '-ir': 1, '-is': 1, '-oat': 0, '-ocsv': 0, '-ojson': 0, '-ojsonl': 0,
        '-oltsv': 0, '-omd': 0, '-oraw': 0, '-otbln': 0, '-ovf': 0, '-oyaml': 0, '-oaq': 0, '-ocrlf': 0,
        '-od': 1, '-oh': 0, '-onowrap': 0, '-onull': 1, '-oq': 1, '-out': 1, '-out-without-guess': 0, '-oz': 1
    }

    options = {
        'ih': False,
        'id': ',',
        'od': ',',
        'oq': '"',
        'oh': False,
        'ocrlf': False,
        'ig': True,
        'out_format': 'csv',
        'in_format': None,
        'query': None,
        'table': None,
        'q': None,
        'onull': '',
    }

    args = sys.argv[1:]
    i = 0
    while i < len(args):
        arg = args[i]

        if not arg.startswith('-'):
            options['query'] = arg
            break

        k, has_eq, v = arg.partition('=')

        if k in FLAG_ARITY:
            arity = FLAG_ARITY[k]
            if arity == 1:
                if has_eq:
                    val = v
                else:
                    if i + 1 < len(args):
                        val = args[i+1]
                        i += 1
                    else:
                        val = ""
                if k == '-id': options['id'] = val
                elif k == '-od': options['od'] = val
                elif k == '-oq': options['oq'] = val
                elif k == '-t': options['table'] = val
                elif k == '-q': options['q'] = val
                elif k == '-onull': options['onull'] = val
            else:
                if has_eq:
                    val = True if v.lower() not in ('false', '0', 'f') else False
                else:
                    val = True

                if k == '-ih': options['ih'] = val
                elif k == '-oh': options['oh'] = val
                elif k == '-ocrlf': options['ocrlf'] = val
                elif k == '-ig': options['ig'] = val
                elif k == '-oat': options['out_format'] = 'at'
                elif k == '-ocsv': options['out_format'] = 'csv'
                elif k == '-ojson': options['out_format'] = 'json'
                elif k == '-ojsonl': options['out_format'] = 'jsonl'
                elif k == '-oltsv': options['out_format'] = 'ltsv'
                elif k == '-omd': options['out_format'] = 'md'
                elif k == '-oraw': options['out_format'] = 'raw'
                elif k == '-otbln': options['out_format'] = 'tbln'
                elif k == '-ovf': options['out_format'] = 'vf'
                elif k == '-oyaml': options['out_format'] = 'yaml'
                elif k == '-icsv': options['in_format'] = 'csv'
                elif k == '-ijson': options['in_format'] = 'json'
                elif k == '-iltsv': options['in_format'] = 'ltsv'
                elif k == '-itbln': options['in_format'] = 'tbln'
                elif k == '-iyaml': options['in_format'] = 'yaml'
        i += 1

    return options

def load_table(conn, fname, options):
    in_format = options.get('in_format')
    ext = os.path.splitext(fname)[1].lower() if fname != '-' else ''

    if not in_format and options.get('ig', True):
        if ext == '.csv': in_format = 'csv'
        elif ext == '.json': in_format = 'json'
        elif ext == '.ltsv': in_format = 'ltsv'
        elif ext == '.tbln': in_format = 'tbln'
        elif ext in ('.yaml', '.yml'): in_format = 'yaml'
        else: in_format = 'csv'
    elif not in_format:
        in_format = 'csv'

    if fname == '-':
        text = sys.stdin.read()
    else:
        try:
            with open(fname, 'r', encoding='utf-8') as f:
                text = f.read()
        except:
            return

    rows = []
    cols = []

    if in_format == 'csv':
        reader = csv.reader(io.StringIO(text), delimiter=options.get('id', ','))
        for i, row in enumerate(reader):
            if i == 0:
                if options.get('ih', False):
                    cols = row
                    continue
                else:
                    cols = [f"c{j+1}" for j in range(len(row))]
            rows.append(row)

    elif in_format == 'json':
        try:
            data = json.loads(text)
            if isinstance(data, list) and len(data) > 0:
                if isinstance(data[0], dict):
                    cols = list(data[0].keys())
                    for item in data:
                        rows.append([str(item.get(c, '')) for c in cols])
                elif isinstance(data[0], list):
                    if options.get('ih', False):
                        cols = data[0]
                        for item in data[1:]:
                            rows.append([str(x) for x in item])
                    else:
                        cols = [f"c{j+1}" for j in range(len(data[0]))]
                        for item in data:
                            rows.append([str(x) for x in item])
            elif isinstance(data, dict):
                cols = list(data.keys())
                rows.append([str(data.get(c, '')) for c in cols])
        except json.JSONDecodeError:
            for line in text.splitlines():
                if line.strip():
                    item = json.loads(line)
                    if not cols:
                        cols = list(item.keys())
                    rows.append([str(item.get(c, '')) for c in cols])

    elif in_format == 'ltsv':
        for i, line in enumerate(text.splitlines()):
            if not line.strip(): continue
            parts = line.split('\t')
            row_dict = {}
            for p in parts:
                k, _, v = p.partition(':')
                row_dict[k] = v
            if i == 0:
                cols = list(row_dict.keys())
            rows.append([row_dict.get(c, '') for c in cols])

    elif in_format == 'tbln':
        for line in text.splitlines():
            line = line.strip()
            if line.startswith('; name: |'):
                cols = [x.strip() for x in line[9:].strip(' |').split('|')]
            elif line.startswith('|'):
                rows.append([x.strip() for x in line.strip(' |').split('|')])

    if not cols:
        cols = ['c1']

    cursor = conn.cursor()
    seen = {}
    unique_cols = []
    for c in cols:
        if not c: c = 'c'
        if c in seen:
            seen[c] += 1
            unique_cols.append(f"{c}_{seen[c]}")
        else:
            seen[c] = 0
            unique_cols.append(c)

    cols_def = ", ".join([f"`{c}` text" for c in unique_cols])
    cursor.execute(f"CREATE TEMPORARY TABLE `{fname}` ({cols_def})")

    if rows:
        placeholders = ",".join(["?"] * len(unique_cols))
        query = f"INSERT INTO `{fname}` VALUES ({placeholders})"
        clean_rows = []
        for r in rows:
            if len(r) > len(unique_cols):
                r = r[:len(unique_cols)]
            elif len(r) < len(unique_cols):
                r = r + [''] * (len(unique_cols) - len(r))
            clean_rows.append(r)
        cursor.executemany(query, clean_rows)

def process_query(sql, conn, options):
    pattern = r"""(
        '[^']*'|
        "[^"]*"|
        `[^`]*`|
        [a-zA-Z0-9_./-]+|
        .
    )"""
    tokens = re.findall(pattern, sql, re.VERBOSE)
    loaded_tables = set()
    for i, t in enumerate(tokens):
        if t.startswith("'") and t.endswith("'"):
            continue

        fname = t
        is_quoted = False
        if (t.startswith('"') and t.endswith('"')) or (t.startswith('`') and t.endswith('`')):
            fname = t[1:-1]
            is_quoted = True

        if fname == '-':
            prev_word = ""
            for j in range(i-1, -1, -1):
                if tokens[j].strip():
                    prev_word = tokens[j].upper()
                    break
            if prev_word not in ('FROM', 'JOIN'):
                continue

        if fname and (os.path.isfile(fname) or fname == '-'):
            if fname not in loaded_tables:
                load_table(conn, fname, options)
                loaded_tables.add(fname)

            if not is_quoted:
                tokens[i] = f"`{fname}`"
            elif t.startswith('"'):
                tokens[i] = f"`{fname}`"

    return "".join(tokens)

def is_numeric(s):
    try:
        float(s)
        return True
    except ValueError:
        return False

def output_results(cursor, options):
    if not cursor.description:
        return
    cols = [desc[0] for desc in cursor.description]
    rows = cursor.fetchall()

    str_rows = []
    for row in rows:
        str_rows.append([str(v) if v is not None else options['onull'] for v in row])

    out_format = options['out_format']

    if out_format == 'csv':
        writer = csv.writer(sys.stdout, delimiter=options['od'], quotechar=options['oq'], lineterminator='\r\n' if options['ocrlf'] else '\n')
        if options['oh']:
            writer.writerow(cols)
        writer.writerows(str_rows)

    elif out_format == 'raw':
        d = options['od']
        if options['oh']:
            print(d.join(cols))
        for r in str_rows:
            print(d.join(r))

    elif out_format == 'json':
        out = []
        for r in str_rows:
            out.append(dict(zip(cols, r)))
        print(json.dumps(out, indent=2))

    elif out_format == 'jsonl':
        for r in str_rows:
            print(json.dumps(dict(zip(cols, r)), separators=(',', ':')))

    elif out_format == 'ltsv':
        for r in str_rows:
            parts = [f"{k}:{v}" for k, v in zip(cols, r)]
            print('\t'.join(parts))

    elif out_format == 'vf':
        max_k_len = max((len(k) for k in cols), default=0)
        for i, r in enumerate(str_rows):
            print(f"---[ {i+1}]------------------------")
            for k, v in zip(cols, r):
                print(f"{k:>{max_k_len}} | {v}")

    elif out_format == 'tbln':
        print("; name: | " + " | ".join(cols) + " |")
        print("; type: | " + " | ".join("text" for _ in cols) + " |")
        for r in str_rows:
            print("| " + " | ".join(r) + " |")

    elif out_format in ('md', 'at'):
        widths = [len(c) for c in cols]
        for r in str_rows:
            for j, v in enumerate(r):
                widths[j] = max(widths[j], len(v))

        if out_format == 'md':
            print("| " + " | ".join(c.center(w) for c, w in zip(cols, widths)) + " |")
            print("|" + "|".join('-' * (w + 2) for w in widths) + "|")
            for r in str_rows:
                print("| " + " | ".join(v.rjust(w) if is_numeric(v) else v.ljust(w) for v, w in zip(r, widths)) + " |")

        elif out_format == 'at':
            sep = "+" + "+".join('-' * (w + 2) for w in widths) + "+"
            print(sep)
            print("| " + " | ".join(c.center(w) for c, w in zip(cols, widths)) + " |")
            print(sep)
            for r in str_rows:
                print("| " + " | ".join(v.rjust(w) if is_numeric(v) else v.ljust(w) for v, w in zip(r, widths)) + " |")
            print(sep)

def main():
    options = parse_args()
    conn = sqlite3.connect(':memory:')

    # Priority:
    # 1. -t option
    # 2. -q option (file)
    # 3. positional query
    if options['table']:
        # when -t is used, it just acts as SELECT * FROM `table`
        query = f"SELECT * FROM `{options['table']}`"
        load_table(conn, options['table'], options)
    else:
        if options['q']:
            try:
                with open(options['q'], 'r', encoding='utf-8') as f:
                    query = f.read()
            except Exception as e:
                print(f"Error reading query file: {e}", file=sys.stderr)
                sys.exit(1)
        else:
            query = options['query']

        if not query:
            sys.exit(0)

        query = process_query(query, conn, options)

    try:
        cursor = conn.cursor()
        cursor.execute(query)
        output_results(cursor, options)
    except sqlite3.Error as e:
        print(f"error: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        conn.close()

if __name__ == '__main__':
    main()
